// 🤣 UTF-16 -> 0xd83e 0xdd23
const str = "🤣";

// 1. 匹配任意一个字符
const reg1 = /^.$/;
console.log(reg1.test(str));    // false

// 2. 匹配 a b 🤣 中的随意一个字符
const reg2 = /^[ac🤣]$/;
console.log(reg2.test("a"));    // true
console.log(reg2.test("c"));    // true
console.log(reg2.test(str));    // false

// 3. 匹配两个 🤣
const reg3 = /🤣{2}/; 
console.log(reg3.test("🤣🤣")); // false

// 🤣 UTF-16 -> 0xd83e 0xdd23
const str = "🤣";

// 1. 匹配任意一个字符
const reg1 = /^.$/u;
console.log(reg1.test(str));    // true

// 2. 匹配 a b 🤣 中的随意一个字符
const reg2 = /^[ac🤣]$/u;
console.log(reg2.test("a"));    // true
console.log(reg2.test("c"));    // true
console.log(reg2.test(str));    // true

// 3. 匹配两个 🤣
const reg3 = /🤣{2}/u; 
console.log(reg3.test("🤣🤣")); // true
